48: # define _C_CTYPE_LOWER_N(N) \
49:    case 'a' + (N): case 'b' + (N): case 'c' + (N): case 'd' + (N): \
50:    case 'e' + (N): case 'f' + (N): \
51:    case 'g' + (N): case 'h' + (N): case 'i' + (N): case 'j' + (N): \
