56: # define _C_CTYPE_UPPER _C_CTYPE_LOWER_N ('A' - 'a')
57: static inline int
58: c_tolower (int c)
59: {
60:   switch (c)
61:     {
62:     _C_CTYPE_UPPER:
63:       return c - 'A' + 'a';
64:     default:
65:       return c;
66:     }
67: }
