69: static int
70: c_strncasecmp (const char *s1, const char *s2, size_t n)
71: {
72:   register const unsigned char *p1 = (const unsigned char *) s1;
73:   register const unsigned char *p2 = (const unsigned char *) s2;
74:   unsigned char c1, c2;
75: 
76:   if (p1 == p2 || n == 0)
77:     return 0;
78: 
79:   do
80:     {
81:       c1 = c_tolower (*p1);
82:       c2 = c_tolower (*p2);
83: 
84:       if (--n == 0 || c1 == '\0')
85: 	break;
86: 
87:       ++p1;
88:       ++p2;
89:     }
90:   while (c1 == c2);
91: 
92:   if (UCHAR_MAX <= INT_MAX)
93:     return c1 - c2;
94:   else
95:     /* On machines where 'char' and 'int' are types of the same size, the
96:        difference of two 'unsigned char' values - including the sign bit -
97:        doesn't fit in an 'int'.  */
98:     return (c1 > c2 ? 1 : c1 < c2 ? -1 : 0);
99: }
100: #else
101: # include <c-strcase.h>
102: #endif
