104: static int
105: set_default_flags (int *flags)
106: {
107:   if (((*flags) & IDN2_TRANSITIONAL) && ((*flags) & IDN2_NONTRANSITIONAL))
108:     return IDN2_INVALID_FLAGS;
109: 
110:   if (((*flags) & (IDN2_TRANSITIONAL | IDN2_NONTRANSITIONAL))
111:       && ((*flags) & IDN2_NO_TR46))
112:     return IDN2_INVALID_FLAGS;
113: 
114:   if (((*flags) & IDN2_ALABEL_ROUNDTRIP)
115:       && ((*flags) & IDN2_NO_ALABEL_ROUNDTRIP))
116:     return IDN2_INVALID_FLAGS;
117: 
118:   if (!((*flags) & (IDN2_NO_TR46 | IDN2_TRANSITIONAL)))
119:     *flags |= IDN2_NONTRANSITIONAL;
120: 
121:   return IDN2_OK;
122: }
