124: static int
125: label (const uint8_t *src, size_t srclen, uint8_t *dst, size_t *dstlen,
126:        int flags)
127: {
128:   size_t plen;
129:   uint32_t *p = NULL;
130:   const uint8_t *src_org = NULL;
131:   uint8_t *src_allocated = NULL;
132:   int rc, check_roundtrip = 0;
133:   size_t tmpl, srclen_org = 0;
134:   uint32_t label_u32[IDN2_LABEL_MAX_LENGTH];
135:   size_t label32_len = IDN2_LABEL_MAX_LENGTH;
136: 
137:   if (_idn2_ascii_p (src, srclen))
138:     {
139:       if (!(flags & IDN2_NO_ALABEL_ROUNDTRIP) && srclen >= 4
140: 	  && memcmp (src, "xn--", 4) == 0)
141: 	{
142: 	  /*
143: 	     If the input to this procedure appears to be an A-label
144: 	     (i.e., it starts in "xn--", interpreted
145: 	     case-insensitively), the lookup application MAY attempt to
146: 	     convert it to a U-label, first ensuring that the A-label is
147: 	     entirely in lowercase (converting it to lowercase if
148: 	     necessary), and apply the tests of Section 5.4 and the
149: 	     conversion of Section 5.5 to that form. */
150: 	  rc = idn2_punycode_decode ((char *) src + 4, srclen - 4,
151: 				     label_u32, &label32_len);
152: 	  if (rc)
153: 	    return rc;
154: 
155: 	  check_roundtrip = 1;
156: 	  src_org = src;
157: 	  srclen_org = srclen;
158: 
159: 	  srclen = IDN2_LABEL_MAX_LENGTH;
160: 	  src = src_allocated =
161: 	    u32_to_u8 (label_u32, label32_len, NULL, &srclen);
162: 	  if (!src)
163: 	    {
164: 	      if (errno == ENOMEM)
165: 		return IDN2_MALLOC;
166: 	      return IDN2_ENCODING_ERROR;
167: 	    }
168: 	}
169:       else
170: 	{
171: 	  if (srclen > IDN2_LABEL_MAX_LENGTH)
172: 	    return IDN2_TOO_BIG_LABEL;
173: 	  if (srclen > *dstlen)
174: 	    return IDN2_TOO_BIG_DOMAIN;
175: 
176: 	  memcpy (dst, src, srclen);
177: 	  *dstlen = srclen;
178: 	  return IDN2_OK;
179: 	}
180:     }
181: 
182:   rc = _idn2_u8_to_u32_nfc (src, srclen, &p, &plen, flags & IDN2_NFC_INPUT);
183:   if (rc != IDN2_OK)
184:     goto out;
185: 
186:   if (!(flags & IDN2_TRANSITIONAL))
187:     {
188:       rc = _idn2_label_test (TEST_NFC |
189: 			     TEST_2HYPHEN |
190: 			     TEST_LEADING_COMBINING |
191: 			     TEST_DISALLOWED |
192: 			     TEST_CONTEXTJ_RULE |
193: 			     TEST_CONTEXTO_WITH_RULE |
194: 			     TEST_UNASSIGNED | TEST_BIDI |
195: 			     ((flags & IDN2_NONTRANSITIONAL) ?
196: 			      TEST_NONTRANSITIONAL : 0) | ((flags &
197: 							    IDN2_USE_STD3_ASCII_RULES)
198: 							   ? 0 :
199: 							   TEST_ALLOW_STD3_DISALLOWED),
200: 			     p, plen);
201: 
202:       if (rc != IDN2_OK)
203: 	goto out;
204:     }
205: 
206:   dst[0] = 'x';
207:   dst[1] = 'n';
208:   dst[2] = '-';
209:   dst[3] = '-';
210: 
211:   tmpl = *dstlen - 4;
212:   rc = idn2_punycode_encode (p, plen, (char *) dst + 4, &tmpl);
213:   if (rc != IDN2_OK)
214:     goto out;
215: 
216: 
217:   *dstlen = 4 + tmpl;
218: 
219:   if (check_roundtrip)
220:     {
221:       if (srclen_org != *dstlen
222: 	  || c_strncasecmp ((char *) src_org, (char *) dst, srclen_org))
223: 	{
224: 	  rc = IDN2_ALABEL_ROUNDTRIP_FAILED;
225: 	  goto out;
226: 	}
227:     }
228:   else if (!(flags & IDN2_NO_ALABEL_ROUNDTRIP))
229:     {
230:       rc = idn2_punycode_decode ((char *) dst + 4, *dstlen - 4,
231: 				 label_u32, &label32_len);
232:       if (rc)
233: 	{
234: 	  rc = IDN2_ALABEL_ROUNDTRIP_FAILED;
235: 	  goto out;
236: 	}
237: 
238:       if (plen != label32_len || u32_cmp (p, label_u32, label32_len))
239: 	{
240: 	  rc = IDN2_ALABEL_ROUNDTRIP_FAILED;
241: 	  goto out;
242: 	}
243:     }
244: 
245:   rc = IDN2_OK;
246: 
247: out:
248:   free (p);
249:   free (src_allocated);
250:   return rc;
251: }
