253: #define TR46_TRANSITIONAL_CHECK \
254:   (TEST_NFC | TEST_2HYPHEN | TEST_HYPHEN_STARTEND | TEST_LEADING_COMBINING | TEST_TRANSITIONAL)
255: #define TR46_NONTRANSITIONAL_CHECK \
256:   (TEST_NFC | TEST_2HYPHEN | TEST_HYPHEN_STARTEND | TEST_LEADING_COMBINING | TEST_NONTRANSITIONAL)
257: 
258: static int
259: _tr46 (const uint8_t *domain_u8, uint8_t **out, int flags)
260: {
261:   size_t len, it;
262:   uint32_t *domain_u32;
263:   int err = IDN2_OK, rc;
264:   int transitional = 0;
265:   int test_flags;
266: 
267:   if (flags & IDN2_TRANSITIONAL)
268:     transitional = 1;
269: 
270:   /* convert UTF-8 to UTF-32 */
271:   if (!(domain_u32 =
272: 	u8_to_u32 (domain_u8, u8_strlen (domain_u8) + 1, NULL, &len)))
273:     {
274:       if (errno == ENOMEM)
275: 	return IDN2_MALLOC;
276:       return IDN2_ENCODING_ERROR;
277:     }
278: 
279:   size_t len2 = 0;
280:   for (it = 0; it < len - 1; it++)
281:     {
282:       IDNAMap map;
283: 
284:       get_idna_map (domain_u32[it], &map);
285: 
286:       if (map_is (&map, TR46_FLG_DISALLOWED))
287: 	{
288: 	  if (domain_u32[it])
289: 	    {
290: 	      free (domain_u32);
291: 	      return IDN2_DISALLOWED;
292: 	    }
293: 	  len2++;
294: 	}
295:       else if (map_is (&map, TR46_FLG_MAPPED))
296: 	{
297: 	  len2 += map.nmappings;
298: 	}
299:       else if (map_is (&map, TR46_FLG_VALID))
300: 	{
301: 	  len2++;
302: 	}
303:       else if (map_is (&map, TR46_FLG_IGNORED))
304: 	{
305: 	  continue;
306: 	}
307:       else if (map_is (&map, TR46_FLG_DEVIATION))
308: 	{
309: 	  if (transitional)
310: 	    {
311: 	      len2 += map.nmappings;
312: 	    }
313: 	  else
314: 	    len2++;
315: 	}
316:       else if (!(flags & IDN2_USE_STD3_ASCII_RULES))
317: 	{
318: 	  if (map_is (&map, TR46_FLG_DISALLOWED_STD3_VALID))
319: 	    {
320: 	      /* valid because UseSTD3ASCIIRules=false, see #TR46 5 */
321: 	      len2++;
322: 	    }
323: 	  else if (map_is (&map, TR46_FLG_DISALLOWED_STD3_MAPPED))
324: 	    {
325: 	      /* mapped because UseSTD3ASCIIRules=false, see #TR46 5 */
326: 	      len2 += map.nmappings;
327: 	    }
328: 	}
329:     }
330: 
331:   /* Exit early if result is too long.
332:    * This avoids excessive CPU usage in punycode encoding, which is O(N^2). */
333:   if (len2 >= IDN2_DOMAIN_MAX_LENGTH)
334:     {
335:       free (domain_u32);
336:       return IDN2_TOO_BIG_DOMAIN;
337:     }
338: 
339:   uint32_t *tmp = (uint32_t *) malloc ((len2 + 1) * sizeof (uint32_t));
340:   if (!tmp)
341:     {
342:       free (domain_u32);
343:       return IDN2_MALLOC;
344:     }
345: 
346:   len2 = 0;
347:   for (it = 0; it < len - 1; it++)
348:     {
349:       uint32_t c = domain_u32[it];
350:       IDNAMap map;
351: 
352:       get_idna_map (c, &map);
353: 
354:       if (map_is (&map, TR46_FLG_DISALLOWED))
355: 	{
356: 	  tmp[len2++] = c;
357: 	}
358:       else if (map_is (&map, TR46_FLG_MAPPED))
359: 	{
360: 	  len2 += get_map_data (tmp + len2, &map);
361: 	}
362:       else if (map_is (&map, TR46_FLG_VALID))
363: 	{
364: 	  tmp[len2++] = c;
365: 	}
366:       else if (map_is (&map, TR46_FLG_IGNORED))
367: 	{
368: 	  continue;
369: 	}
370:       else if (map_is (&map, TR46_FLG_DEVIATION))
371: 	{
372: 	  if (transitional)
373: 	    {
374: 	      len2 += get_map_data (tmp + len2, &map);
375: 	    }
376: 	  else
377: 	    tmp[len2++] = c;
378: 	}
379:       else if (!(flags & IDN2_USE_STD3_ASCII_RULES))
380: 	{
381: 	  if (map_is (&map, TR46_FLG_DISALLOWED_STD3_VALID))
382: 	    {
383: 	      tmp[len2++] = c;
384: 	    }
385: 	  else if (map_is (&map, TR46_FLG_DISALLOWED_STD3_MAPPED))
386: 	    {
387: 	      len2 += get_map_data (tmp + len2, &map);
388: 	    }
389: 	}
390:     }
391:   free (domain_u32);
392: 
393:   /* Normalize to NFC */
394:   tmp[len2] = 0;
395:   domain_u32 = u32_normalize (UNINORM_NFC, tmp, len2 + 1, NULL, &len);
396:   free (tmp);
397:   tmp = NULL;
398: 
399:   if (!domain_u32)
400:     {
401:       if (errno == ENOMEM)
402: 	return IDN2_MALLOC;
403:       return IDN2_ENCODING_ERROR;
404:     }
405: 
406:   /* split into labels and check */
407:   uint32_t *e, *s;
408:   for (e = s = domain_u32; *e; s = e)
409:     {
410:       while (*e && *e != '.')
411: 	e++;
412: 
413:       if (e - s >= 4 && s[0] == 'x' && s[1] == 'n' && s[2] == '-'
414: 	  && s[3] == '-')
415: 	{
416: 	  /* decode punycode and check result non-transitional */
417: 	  size_t ace_len;
418: 	  uint32_t name_u32[IDN2_LABEL_MAX_LENGTH];
419: 	  size_t name_len = IDN2_LABEL_MAX_LENGTH;
420: 	  uint8_t *ace;
421: 
422: 	  ace = u32_to_u8 (s + 4, e - s - 4, NULL, &ace_len);
423: 	  if (!ace)
424: 	    {
425: 	      free (domain_u32);
426: 	      if (errno == ENOMEM)
427: 		return IDN2_MALLOC;
428: 	      return IDN2_ENCODING_ERROR;
429: 	    }
430: 
431: 	  rc = idn2_punycode_decode ((char *) ace, ace_len,
432: 				     name_u32, &name_len);
433: 
434: 	  free (ace);
435: 
436: 	  if (rc)
437: 	    {
438: 	      free (domain_u32);
439: 	      return rc;
440: 	    }
441: 
442: 	  test_flags = TR46_NONTRANSITIONAL_CHECK;
443: 
444: 	  if (!(flags & IDN2_USE_STD3_ASCII_RULES))
445: 	    test_flags |= TEST_ALLOW_STD3_DISALLOWED;
446: 
447: 	  if ((rc = _idn2_label_test (test_flags, name_u32, name_len)))
448: 	    err = rc;
449: 	}
450:       else
451: 	{
452: 	  test_flags =
453: 	    transitional ? TR46_TRANSITIONAL_CHECK :
454: 	    TR46_NONTRANSITIONAL_CHECK;
455: 
456: 	  if (!(flags & IDN2_USE_STD3_ASCII_RULES))
457: 	    test_flags |= TEST_ALLOW_STD3_DISALLOWED;
458: 
459: 	  if ((rc = _idn2_label_test (test_flags, s, e - s)))
460: 	    err = rc;
461: 	}
462: 
463:       if (*e)
464: 	e++;
465:     }
466: 
467:   if (err == IDN2_OK && out)
468:     {
469:       uint8_t *_out = u32_to_u8 (domain_u32, len, NULL, &len);
470:       free (domain_u32);
471: 
472:       if (!_out)
473: 	{
474: 	  if (errno == ENOMEM)
475: 	    return IDN2_MALLOC;
476: 	  return IDN2_ENCODING_ERROR;
477: 	}
478: 
479:       *out = _out;
480:     }
481:   else
482:     free (domain_u32);
483: 
484:   return err;
485: }
