647:  *   conversion from locale to UTF-8 fails then %IDN2_ICONV_FAIL is
648:  *   returned, if the output domain or any label would have been too
649:  *   long %IDN2_TOO_BIG_DOMAIN or %IDN2_TOO_BIG_LABEL is returned, or
650:  *   another error code is returned.
651:  *
652:  * Since: 0.1
653:  **/
654: int
655: idn2_lookup_ul (const char *src, char **lookupname, int flags)
656: {
657:   uint8_t *utf8src = NULL;
658:   int rc;
659: 
660:   if (src)
661:     {
662:       const char *encoding = locale_charset ();
663: 
664:       utf8src = u8_strconv_from_encoding (src, encoding, iconveh_error);
665: 
666:       if (!utf8src)
667: 	{
668: 	  if (errno == ENOMEM)
669: 	    return IDN2_MALLOC;
670: 	  return IDN2_ICONV_FAIL;
671: 	}
672:     }
673: 
674:   rc = idn2_lookup_u8 (utf8src, (uint8_t **) lookupname,
675: 		       flags | IDN2_NFC_INPUT);
676: 
677:   free (utf8src);
678: 
679:   return rc;
680: }
