718:  *   output label would have been too long %IDN2_TOO_BIG_LABEL is
719:  *   returned, or another error code is returned.
720:  *
721:  * Since: 2.0.0
722:  **/
723: int
724: idn2_to_ascii_4i (const uint32_t *input, size_t inlen, char *output,
725: 		  int flags)
726: {
727:   char *out;
728:   int rc;
729: 
730:   if (!input)
731:     {
732:       if (output)
733: 	*output = 0;
734:       return IDN2_OK;
735:     }
736: 
737:   rc = idn2_to_ascii_4i2 (input, inlen, &out, flags);
738:   if (rc == IDN2_OK)
739:     {
740:       size_t len = strlen (out);
