54: G_GNUC_IDN2_ATTRIBUTE_PURE static int
55: _isNFC (uint32_t *label, size_t len)
56: {
57:   int lastCanonicalClass = 0;
58:   int result = 1;
59:   size_t it;
60: 
61:   for (it = 0; it < len; it++)
62:     {
63:       uint32_t ch = label[it];
64: 
65:       // supplementary code point
66:       if (ch >= 0x10000)
67: 	it++;
68: 
69:       int canonicalClass = uc_combining_class (ch);
70:       if (lastCanonicalClass > canonicalClass && canonicalClass != 0)
71: 	return 0;
72: 
73:       NFCQCMap *map = get_nfcqc_map (ch);
74:       if (map)
75: 	{
76: 	  if (map->check)
77: 	    return 0;
78: 	  result = -1;
79: 	}
80: 
81:       lastCanonicalClass = canonicalClass;
82:     }
83: 
84:   return result;
