36: int
37: _idn2_contextj_rule (const uint32_t *label, size_t llen, size_t pos)
38: {
39:   uint32_t cp;
40: 
41:   if (llen == 0)
42:     return IDN2_OK;
43: 
44:   cp = label[pos];
45: 
46:   if (!_idn2_contextj_p (cp))
47:     return IDN2_OK;
48: 
49:   switch (cp)
50:     {
51:     case 0x200C:		/* ZERO WIDTH NON-JOINER */
52:       if (pos > 0)
53: 	{
54: 	  /* If Canonical_Combining_Class(Before(cp)) .eq.  Virama Then True; */
55: 	  uint32_t before_cp = label[pos - 1];
56: 	  int cc = uc_combining_class (before_cp);
57: 	  if (cc == UC_CCC_VR)
58: 	    return IDN2_OK;
59: 	}
60: 
61:       /* See http://permalink.gmane.org/gmane.ietf.idnabis/6980 for
62:          clarified rule. */
63: 
64:       if (pos == 0 || pos == llen - 1)
65: 	return IDN2_CONTEXTJ;
66: 
67:       {
68: 	int jt;
69: 	size_t tmp;
70: 
71: 	/* Search backwards. */
72: 	for (tmp = pos - 1;; tmp--)
73: 	  {
74: 	    jt = uc_joining_type (label[tmp]);
75: 	    if (jt == UC_JOINING_TYPE_L || jt == UC_JOINING_TYPE_D)
76: 	      break;
77: 	    if (tmp == 0)
78: 	      return IDN2_CONTEXTJ;
79: 	    if (jt == UC_JOINING_TYPE_T)
80: 	      continue;
81: 	    return IDN2_CONTEXTJ;
82: 	  }
83: 
84: 	/* Search forward. */
85: 	for (tmp = pos + 1; tmp < llen; tmp++)
86: 	  {
87: 	    jt = uc_joining_type (label[tmp]);
88: 	    if (jt == UC_JOINING_TYPE_R || jt == UC_JOINING_TYPE_D)
89: 	      break;
90: 	    if (tmp == llen - 1)
91: 	      return IDN2_CONTEXTJ;
92: 	    if (jt == UC_JOINING_TYPE_T)
93: 	      continue;
94: 	    return IDN2_CONTEXTJ;
95: 	  }
96:       }
97: 
98:       return IDN2_OK;
99:       break;
100: 
101:     case 0x200D:		/* ZERO WIDTH JOINER */
102:       if (pos > 0)
103: 	{
104: 	  uint32_t before_cp = label[pos - 1];
105: 	  int cc = uc_combining_class (before_cp);
106: 	  if (cc == UC_CCC_VR)
107: 	    return IDN2_OK;
108: 	}
109:       return IDN2_CONTEXTJ;
110:     }
111: 
112:   return IDN2_CONTEXTJ_NO_RULE;
113: }
