29: #include <config.h>
30: 
31: #include "idn2.h"
32: 
33: #include <errno.h>		/* errno */
34: #include <stdlib.h>		/* free */
35: 
36: #include <unitypes.h>
37: #include <uniconv.h>		/* u8_strconv_from_locale */
38: #include <unistr.h>		/* u32_to_u8 */
39: 
40: #include "idna.h"		/* _idn2_label_test */
41: 
42: /**
43:  * idn2_register_u8:
44:  * @ulabel: input zero-terminated UTF-8 and Unicode NFC string, or NULL.
45:  * @alabel: input zero-terminated ACE encoded string (xn--), or NULL.
46:  * @insertname: newly allocated output variable with name to register in DNS.
47:  * @flags: optional #idn2_flags to modify behaviour.
48:  *
49:  * Perform IDNA2008 register string conversion on domain label @ulabel
50:  * and @alabel, as described in section 4 of RFC 5891.  Note that the
51:  * input @ulabel must be encoded in UTF-8 and be in Unicode NFC form.
52:  *
53:  * Pass %IDN2_NFC_INPUT in @flags to convert input @ulabel to NFC form
54:  * before further processing.
55:  *
56:  * It is recommended to supply both @ulabel and @alabel for better
57:  * error checking, but supplying just one of them will work.  Passing
58:  * in only @alabel is better than only @ulabel.  See RFC 5891 section
59:  * 4 for more information.
60:  *
61:  * After version 0.11: @insertname may be NULL to test conversion of @src
62:  * without allocating memory.
63:  *
64:  * Returns: On successful conversion %IDN2_OK is returned, when the
65:  *   given @ulabel and @alabel does not match each other
66:  *   %IDN2_UALABEL_MISMATCH is returned, when either of the input
67:  *   labels are too long %IDN2_TOO_BIG_LABEL is returned, when @alabel
68:  *   does does not appear to be a proper A-label %IDN2_INVALID_ALABEL
69:  *   is returned, or another error code is returned.
70:  **/
71: int
72: idn2_register_u8 (const uint8_t *ulabel, const uint8_t *alabel,
73: 		  uint8_t **insertname, int flags)
74: {
75:   int rc;
76: 
77:   if (ulabel == NULL && alabel == NULL)
78:     {
79:       if (insertname)
80: 	*insertname = NULL;
81:       return IDN2_OK;
82:     }
83: 
84:   if (alabel)
85:     {
86:       size_t alabellen = strlen ((char *) alabel), u32len =
87: 	IDN2_LABEL_MAX_LENGTH * 4;
88:       uint32_t u32[IDN2_DOMAIN_MAX_LENGTH * 4];
89:       uint8_t *tmp;
90:       uint8_t u8[IDN2_DOMAIN_MAX_LENGTH + 1];
91:       size_t u8len;
92: 
93:       if (alabellen > IDN2_LABEL_MAX_LENGTH)
94: 	return IDN2_TOO_BIG_LABEL;
95: 
96:       if (alabellen <= 4)
97: 	return IDN2_INVALID_ALABEL;
98:       if (alabel[0] != 'x'
99: 	  || alabel[1] != 'n' || alabel[2] != '-' || alabel[3] != '-')
100: 	return IDN2_INVALID_ALABEL;
101: 
102:       if (!_idn2_ascii_p (alabel, alabellen))
103: 	return IDN2_INVALID_ALABEL;
104: 
105:       rc = idn2_punycode_decode ((char *) alabel + 4, alabellen - 4,
106: 				 u32, &u32len);
107:       if (rc != IDN2_OK)
108: 	return rc;
109: 
110:       u8len = sizeof (u8);
111:       if (u32_to_u8 (u32, u32len, u8, &u8len) == NULL)
112: 	return IDN2_ENCODING_ERROR;
113:       u8[u8len] = '\0';
114: 
115:       if (ulabel)
116: 	{
117: 	  if (strcmp ((char *) ulabel, (char *) u8) != 0)
118: 	    return IDN2_UALABEL_MISMATCH;
119: 	}
120: 
121:       rc = idn2_register_u8 (u8, NULL, &tmp, 0);
122:       if (rc != IDN2_OK)
123: 	return rc;
124: 
125:       rc = strcmp ((char *) alabel, (char *) tmp);
126:       free (tmp);
127:       if (rc != 0)
128: 	return IDN2_UALABEL_MISMATCH;
129: 
130:       if (insertname)
131: 	{
132: 	  uint8_t *m = (uint8_t *) strdup ((char *) alabel);
133: 	  if (!m)
134: 	    return IDN2_MALLOC;
135: 
136: 	  *insertname = m;
137: 	}
138:     }
139:   else				/* ulabel only */
140:     {
141:       size_t ulabellen = u8_strlen (ulabel);
142:       uint32_t *u32;
143:       size_t u32len;
144:       size_t tmpl;
145:       uint8_t tmp[IDN2_LABEL_MAX_LENGTH + 1];
146: 
147:       if (_idn2_ascii_p (ulabel, ulabellen))
148: 	{
149: 	  if (ulabellen > IDN2_LABEL_MAX_LENGTH)
150: 	    return IDN2_TOO_BIG_LABEL;
151: 
152: 	  if (insertname)
153: 	    {
154: 	      uint8_t *m = (uint8_t *) strdup ((char *) ulabel);
155: 	      if (!m)
156: 		return IDN2_MALLOC;
157: 	      *insertname = m;
158: 	    }
159: 	  return IDN2_OK;
160: 	}
161: 
162:       rc = _idn2_u8_to_u32_nfc (ulabel, ulabellen, &u32, &u32len,
163: 				flags & IDN2_NFC_INPUT);
164:       if (rc != IDN2_OK)
165: 	return rc;
166: 
167:       rc = _idn2_label_test (TEST_NFC
168: 			     | TEST_DISALLOWED
169: 			     | TEST_UNASSIGNED
170: 			     | TEST_2HYPHEN
171: 			     | TEST_HYPHEN_STARTEND
172: 			     | TEST_LEADING_COMBINING
173: 			     | TEST_CONTEXTJ_RULE
174: 			     | TEST_CONTEXTO_RULE | TEST_BIDI, u32, u32len);
175:       if (rc != IDN2_OK)
176: 	{
177: 	  free (u32);
178: 	  return rc;
179: 	}
180: 
181:       tmp[0] = 'x';
182:       tmp[1] = 'n';
183:       tmp[2] = '-';
184:       tmp[3] = '-';
185: 
186:       tmpl = IDN2_LABEL_MAX_LENGTH - 4;
187:       rc = idn2_punycode_encode (u32, u32len, (char *) tmp + 4, &tmpl);
188:       free (u32);
189:       if (rc != IDN2_OK)
190: 	return rc;
191: 
192:       tmp[4 + tmpl] = '\0';
193: 
194:       if (insertname)
195: 	{
196: 	  uint8_t *m = (uint8_t *) strdup ((char *) tmp);
197: 	  if (!m)
198: 	    return IDN2_MALLOC;
199: 	  *insertname = m;
200: 	}
201:     }
202: 
203:   return IDN2_OK;
204: }
